{"name": "enable_rls_on_all_tables", "query": "
-- ============================================================
-- MIGRATION: Enable RLS on All Five Tables
-- ============================================================

ALTER TABLE public.users             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channels          ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channel_moderators ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.posts             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comments          ENABLE ROW LEVEL SECURITY;
"}

{"name": "create_rls_performance_indexes", "query": "
-- ============================================================
-- MIGRATION: Performance Indexes for RLS Policies
-- ============================================================
-- RLS policies perform table scans if the columns they filter
-- on are not indexed. These indexes ensure O(log n) lookups.
-- ============================================================

-- users table: Lookups by id (already PK), username
CREATE INDEX IF NOT EXISTS idx_users_id
  ON public.users(id);

-- channels table: Lookups by owner_id (used in ownership checks)
CREATE INDEX IF NOT EXISTS idx_channels_owner_id
  ON public.channels(owner_id);

-- channel_moderators: Composite index for fast (channel_id, user_id) lookups
-- (already a PK, but adding individual indexes for single-column filter paths)
CREATE INDEX IF NOT EXISTS idx_channel_moderators_channel_id
  ON public.channel_moderators(channel_id);

CREATE INDEX IF NOT EXISTS idx_channel_moderators_user_id
  ON public.channel_moderators(user_id);

-- posts table: Lookups by author_id and channel_id
CREATE INDEX IF NOT EXISTS idx_posts_author_id
  ON public.posts(author_id);

CREATE INDEX IF NOT EXISTS idx_posts_channel_id
  ON public.posts(channel_id);

-- Composite for "posts in a channel by author" queries
CREATE INDEX IF NOT EXISTS idx_posts_channel_id_author_id
  ON public.posts(channel_id, author_id);

-- comments table: Lookups by author_id and post_id
CREATE INDEX IF NOT EXISTS idx_comments_author_id
  ON public.comments(author_id);

CREATE INDEX IF NOT EXISTS idx_comments_post_id
  ON public.comments(post_id);

-- Composite for "comments on a post by author" queries
CREATE INDEX IF NOT EXISTS idx_comments_post_id_author_id
  ON public.comments(post_id, author_id);
"}
